// NEW: Webhook for when a player requests a new phrase
export const sendPhraseRequestNotification = async ({ requester, phrase, bingoType, commitInfo }) => {
    const webhookUrl = null || null;
    if (!webhookUrl) {
        console.warn("Bingo webhook URL not configured. Skipping notification.");
        return;
    }

    const phraseLines = phrase.split('\n'); // Split the phrase into multiple phrases
    let embedFields = [];

    // Add each line of the phrase as a separate field
    phraseLines.forEach((line, index) => {
        embedFields.push({ name: `Phrase Line ${index + 1}`, value: `\n`, inline: false });
    });

    // Add requester and bingoType fields
    embedFields.push({ name: "Demande pour", value: bingoType || 'Unknown Game', inline: true });
    embedFields.push({ name: "Demandé par", value: requester || 'Anonymous', inline: true });

    const embedData = {
        title: "📝 Nouvelle demande de phrase de bingo",
        description: `Une nouvelle phrase a été demandée pour examen.`,
        color: 0x7289DA, // Discord Blurple
        fields: embedFields,
        footerText: "PHMC Bingo",
    };

    await sendDiscordWebhookInternal(webhookUrl, embedData, commitInfo);
};


// --- MODIFIED: General PHMC Recruitment Webhook Sender ---
// Exportée pour être réutilisée par le pipeline de candidatures (Lot 6) :
// "Enregistrer et Candidater" envoie cette même notification, sans passer par
// handlePhmcRecruitmentCopyAndNotify (qui copie aussi dans le presse-papiers,
// non pertinent ici puisque la candidature est persistée dans jobApplications).
export const sendPhmcRecruitmentWebhook = async ({
    webhookUrl,
    formData,
    commitInfo,
    actionMessage,
    selectOptions,
    formDefinition, 
}) => {
    const {
        applicantTitleAndFullName,
        recruitmentPosition,
        applicantPhone,
        applicantEmail,
        oocUcpName,
        oocDiscord,
    } = formData;

    let positionDetailsSource = null;
    if (formDefinition) {
        switch (formDefinition.titleKey) {
            case "phmcGeneralApplication":
                positionDetailsSource = getCategoryPositions(selectOptions, 'medecine');
                break;
            case "phmcPsychApplication":
                positionDetailsSource = getCategoryPositions(selectOptions, 'psychologie');
                break;
            case "phmcAdminApplication":
                positionDetailsSource = getCategoryPositions(selectOptions, 'administration');
                break;
            case "phmcNursingApplication":
                positionDetailsSource = getCategoryPositions(selectOptions, 'soinsInfirmiers');
                break;
            case "phmcCoronerRecruitmentApplication":
                positionDetailsSource = getCategoryPositions(selectOptions, 'medecineLegale');
                break;
            case "phmcEMSApplication":
                positionDetailsSource = getCategoryPositions(selectOptions, 'paramedical');
                break;
            default:
                console.warn(`No specific positionDetailsSource mapping for PHMC Recruitment form: ${formDefinition.titleKey} in webhook.`);
        }
    }

    const positionDisplayName = positionDetailsSource?.[recruitmentPosition]?.nom || recruitmentPosition || "N/A";
    const formNameForTitle = formDefinition?.name || "PHMC Recruitment Application";

    const fields = [
        { name: "Nom du demandeur", value: applicantTitleAndFullName || "N/A", inline: true },
        { name: "Poste postulé", value: positionDisplayName, inline: true },
        { name: "Coordonnées", value: `Tél: ${applicantPhone || 'N/A'} — Email: ${applicantEmail || 'N/A'}`, inline: false },
        { name: "Nom UCP OOC", value: oocUcpName || "N/A", inline: true },
        { name: "Nom Discord", value: oocDiscord || "N/A", inline: true },
        { name: "Horodatage", value: new Date().toLocaleString(), inline: false },
        { name: "Action", value: actionMessage || "Demande traitée", inline: false },
    ];

    const embedData = {
        title: `${formNameForTitle} Notification`,
        color: 0x007bff, 
        fields: fields,
        footerText: "PHMC Formulaire de Recrutement", 
    };

    await sendDiscordWebhookInternal(webhookUrl, embedData, commitInfo);
};

export const handlePhmcRecruitmentCopyAndNotify = async ({
    formData,
    getBBCodeContent,
    showNotification,
    commitInfo,
    selectOptions,
    formDefinition, 
}) => {
    const bbCodeToCopy = getBBCodeContent();
    const formName = formDefinition?.name || "PHMC Demande de Recrutement";

    if (!bbCodeToCopy) {
        showNotification(`Impossible de générer le BBCode ${formName}. Copie ignorée.`, 'error');
        Sentry.captureMessage(`getBBCodeContent returned null/undefined for ${formName}`, 'error');
        return false;
    }

    const copied = await copyToClipboard(bbCodeToCopy, showNotification, `${formName} BBCode copié dans le presse-papiers !`);

    if (copied) {
        const discordWebhookUrl = null || null;

        if (discordWebhookUrl) {
            await sendPhmcRecruitmentWebhook({
                webhookUrl: discordWebhookUrl,
                formData,
                commitInfo,
                actionMessage: `${formName} BBCode copié`,
                selectOptions,
                formDefinition, 
            });
        } else {
            console.warn(`Discord webhook URL for ${formName} not set, skipping notification.`);
        }
    }
    return !!copied;
};

